using Microsoft.Extensions.AI;
using OpenAI;
using System.ComponentModel;

Console.WriteLine("Research Agent Starting...");

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key";
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(modelName).AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var researchTools = new ResearchTools();
var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine() ?? "artificial intelligence";

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (perform multiple searches with different queries)
        2. Taking notes on key findings as you go
        3. Finally, retrieving all your notes and providing a comprehensive summary

        Always take notes on important findings before moving to the next search.
        When you have gathered enough information, retrieve your notes and produce a final summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

Console.WriteLine($"\nResearching: {topic}\n");

var response = await chatClient.GetResponseAsync(messages, chatOptions);
Console.WriteLine("\n--- Research Summary ---\n");
Console.WriteLine(response.Text);

// Display collected notes
var notes = researchTools.GetAllNotes();
if (notes.Count > 0)
{
    Console.WriteLine("\n--- Collected Notes ---\n");
    for (int i = 0; i < notes.Count; i++)
    {
        Console.WriteLine($"  {i + 1}. {notes[i]}");
    }
}

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    [Description("Search the web for information on a given query. Returns relevant search results.")]
    public async Task<string> SearchWeb([Description("The search query string")] string query)
    {
        Console.WriteLine($"  [Tool] Searching: \"{query}\"");
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var request = new HttpRequestMessage(HttpMethod.Get,
                $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1");
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();
            var content = await response.Content.ReadAsStringAsync();

            if (string.IsNullOrWhiteSpace(content) || content.Length < 50)
            {
                return $"Search results for '{query}': No detailed results available. " +
                       "Try rephrasing the query or searching for more specific terms.";
            }
            return $"Search results for '{query}':\n{content[..Math.Min(content.Length, 4000)]}";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note taken: \"{note[..Math.Min(note.Length, 80)]}...\"");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all notes taken during research so far.")]
    public string GetNotes()
    {
        Console.WriteLine("  [Tool] Retrieving all notes...");
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return "Your research notes:\n" +
               string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public List<string> GetAllNotes() => [.. _notes];
}

